import{z as d,x as n,o,c as i,q as E,j as s,D as e,d as t,s as c,S as A}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"宏融合与微融合","description":"","frontmatter":{"title":"宏融合与微融合","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/macro-micro-fusion.md","filePath":"cs/macro-micro-fusion.md","lastUpdated":1791413859000}'),p={name:"cs/macro-micro-fusion.md"};function l(B,a,m,D,u,_){const r=n("Mermaid");return o(),i("div",null,[a[2]||(a[2]=E('<h1 id="宏融合与微融合" tabindex="-1">宏融合与微融合 <a class="header-anchor" href="#宏融合与微融合" aria-label="Permalink to &quot;宏融合与微融合&quot;">​</a></h1><div class="epigraph"><p>比较加分支、访存加运算在 ISA 里是两条；若始终一起出现，译码可以把它们收成一个 uop 或一个发射槽，前端宽度立刻便宜一号。</p><footer>—— 据 Intel 对 macro-fusion 与 micro-fusion 的公开描述；Hennessy and Patterson, CA:AQA 整理</footer></div><p><a href="/cs/loop-stream-buffer">上一课</a>按 uop 计数决定循环能不能锁定。<a href="/cs/fetch-decode-width">取指带宽</a> 的上限以「条」计。本课不重讲 LSB 检测。缺口是<strong>融合：在译码把宏指令或微操作合并，使窗口与前端看到的条数变少</strong>，而不改程序员看见的 ISA。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>x86 的 <code>cmp</code>/<code>test</code> 后面几乎总跟着 <code>jcc</code>：两条宏指令、两个 uop、两次重命名。地址生成与 load 也常跟 ALU 成对（<code>add rax, [rbx]</code>）。若硬件总是拆开，<a href="/cs/issue-queue-wakeup">发射队列</a> 和 <a href="/cs/prf-free-list">PRF</a> 都为这对「形影不离」的东西付双倍。缺口不是新预测器，而是<strong>识别固定搭配，合成更少的内部操作</strong>。</p><p><span class="marginnote">宏融合：两条宏指令 → 一个 uop（典型是 ALU+jcc）。微融合：一条宏指令内部的 store/load 地址与数据合成「一条」在部分流水段里占一个槽，到后端再裂开。</span></p><p><span class="marginnote">直觉类比：宏融合像服务员把「下单」和「加急」并成一句话报给后厨，点菜单（前端）少写一行；微融合是把同一道菜的「取料地点」和「做法」写在同一格里。窗口里行数变少，但菜还是那些菜——程序员看见的 ISA 一口没变。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>译码器看相邻宏指令或一条宏指令的 uop 模板：符合白名单（如 <code>cmp</code>+条件跳、<code>mem</code>+ALU）则输出融合后的内部操作，RAT/IQ 只分配一次（或在指定级再裂）。核对与异常仍按架构的两条（或一条复杂指令）处理：调试器看见的 RIP 不能因为融合而跳错。</p>',9)),(o(),s(A,null,{default:e(()=>[c(r,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20M1%5B%22cmp%20%2F%20test%22%5D%20--%3E%20FUSE%5B%22%E5%AE%8F%E8%9E%8D%E5%90%88%22%5D%0A%20%20M2%5B%22jcc%22%5D%20--%3E%20FUSE%0A%20%20FUSE%20--%3E%20UOP%5B%22%E4%B8%80%E4%B8%AA%E5%88%86%E6%94%AF%E7%B1%BB%20uop%22%5D%0A%20%20LD%5B%22load%20%E5%9C%B0%E5%9D%80%2B%E6%95%B0%E6%8D%AE%22%5D%20--%3E%20MF%5B%22%E5%BE%AE%E8%9E%8D%E5%90%88%E8%BF%9B%E5%8F%91%E5%B0%84%22%5D%0A%20%20ALU%5B%22ALU%22%5D%20--%3E%20MF%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[t(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E('<p>RISC-V 定长、正交，融合收益小；压缩指令已经在编码层减带宽。本课以 CISC 前端为主要动机，不把融合写成 RISC 必选项。</p><p><span class="marginnote">数字实例：译码每拍 4 个 uop。不融合时 <code>cmp</code>+<code>jcc</code> 占两槽，一拍最多喂 4 条指令；融合后两指令合一槽，同样 4 槽能容纳 5 条指令——前端等效带宽加 25%，循环也更容易整体塞进锁定缓冲。</span></p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>有效 \\(D\\) 上升：同样的取指字节产生更少 IQ 项，LSB 更容易装下循环。ROB 计数有的实现按 uop、有的按宏指令，影响「融合是否占用两个提交槽」——精确异常要以架构指令为界，不能把 <code>jcc</code> 的异常算到 <code>cmp</code> 上。</p><p>与预测：融合后的 uop 仍是一条分支，gshare/TAGE 的 PC 通常用跳转的 IP。</p>',5)),(o(),s(A,null,{default:e(()=>[c(r,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20TD%0A%20%20SEQ%5B%22%E5%8F%96%E6%8C%87%E6%8C%89%E6%9D%A1%E6%95%B0%E8%AE%A1%3A%20cmp%2C%20jcc%2C%20add%2C%20sub%22%5D%20--%3E%20DEC%5B%22%E8%AF%91%E7%A0%81%E5%99%A8%E5%AF%B9%E7%85%A7%E7%99%BD%E5%90%8D%E5%8D%95%22%5D%0A%20%20DEC%20--%3E%20F%5B%22cmp%2Bjcc%20%E6%90%AD%E9%85%8D%E5%91%BD%E4%B8%AD%3A%20%E8%BE%93%E5%87%BA%201%20%E4%B8%AA%E8%9E%8D%E5%90%88%20uop%22%5D%0A%20%20F%20--%3E%20IQ%5B%22%E9%87%8D%E5%91%BD%E5%90%8D%2FIQ%20%E5%8F%AA%E5%88%86%E9%85%8D%201%20%E9%A1%B9%3A%20%E6%9C%89%E6%95%88%E5%AE%BD%E5%BA%A6%E4%B8%8A%E5%8D%87%22%5D%0A%20%20DEC%20--%3E%20N%5B%22%E6%90%AD%E9%85%8D%E8%A2%AB%E5%A4%B9%E6%9D%82%E6%8C%87%E4%BB%A4%E6%89%93%E6%96%AD%22%5D%0A%20%20N%20--%3E%20FB%5B%22%E9%80%80%E5%9B%9E%E4%B8%A4%E6%9D%A1%E7%8B%AC%E7%AB%8B%20uop%22%5D%0A%20%20F%20--%3E%20RET%5B%22%E6%8F%90%E4%BA%A4%E4%BB%8D%E6%8C%89%E6%9E%B6%E6%9E%84%E6%8C%87%E4%BB%A4%E8%BE%B9%E7%95%8C%2C%20%E5%BC%82%E5%B8%B8%E5%90%84%E5%BD%92%E5%90%84%E6%9D%A1%22%5D%0A%20%20IQ%20--%3E%20RET%0A%20%20FB%20--%3E%20RET%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[t(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=E('<p><span class="marginnote">为什么重要：融合只是内部打包，异常必须仍按架构指令边界报。若把 <code>jcc</code> 的缺页算到 <code>cmp</code> 头上，调试器看到的 RIP 会错位，断点与信号处理全乱——所以核对要么拆回两条，要么按宏指令界提交。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把宏融合白名单写成可移植 ABI。也不引入 VLIW 的编译器打包——那是后课 EPIC，软件可见。融合失败（中间夹杂别的指令、64 位某些模式限制）则退回两条。</p><p>后课默认：前端条数可以少于 ISA 条数。这些 uop 最终仍要按序提交，异常与中断看见的是架构状态，下一课退休。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>宏融合减宏指令条数，微融合减部分流水的槽占用。</li><li>精确性仍按 ISA 指令边界，不以融合后的内部形态为准。</li><li>提交与精确异常是下一课退休。</li><li>出处：Intel 软件开发者手册 / 优化手册；Hennessy and Patterson, <em>CA:AQA</em>。</li></ul>',6))])}const C=d(p,[["render",l]]);export{f as __pageData,C as default};
